class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        return sum(nums[i] for i in range(n)
                   if (i - k < 0 or nums[i] > nums[i - k])
                   and (i + k >= n or nums[i] > nums[i + k]))

c.cpp:
class Solution {
public:
    int sumOfGoodNumbers(vector<int>& nums, int k) {
        int n = nums.size(), ans = 0;
        for (int i = 0; i < n; i++) {
            bool ok = true;
            if (i - k >= 0 && nums[i] <= nums[i - k]) ok = false;
            if (i + k < n && nums[i] <= nums[i + k]) ok = false;
            if (ok) ans += nums[i];
        }
        return ans;
    }
};

